-- Milestone 11: messaging + workflows
CREATE TABLE "MessageTemplate" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "channel" TEXT NOT NULL, "subject" TEXT, "body" TEXT NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MessageTemplate_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MessageTemplate_organizationId_channel_idx" ON "MessageTemplate"("organizationId","channel");
CREATE TABLE "Broadcast" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "channel" TEXT NOT NULL, "templateId" TEXT, "subject" TEXT, "body" TEXT NOT NULL, "audienceType" TEXT NOT NULL, "audienceStage" TEXT, "status" TEXT NOT NULL DEFAULT 'draft', "totalRecipients" INTEGER NOT NULL DEFAULT 0, "sentCount" INTEGER NOT NULL DEFAULT 0, "failedCount" INTEGER NOT NULL DEFAULT 0, "createdById" TEXT NOT NULL, "sentAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Broadcast_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Broadcast_organizationId_createdAt_idx" ON "Broadcast"("organizationId","createdAt");
CREATE TABLE "MessageDelivery" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "broadcastId" TEXT, "workflowRunId" TEXT, "channel" TEXT NOT NULL, "recipientType" TEXT NOT NULL, "recipientId" TEXT, "address" TEXT NOT NULL, "status" TEXT NOT NULL, "providerMessageId" TEXT, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MessageDelivery_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MessageDelivery_organizationId_broadcastId_idx" ON "MessageDelivery"("organizationId","broadcastId");
CREATE INDEX "MessageDelivery_organizationId_createdAt_idx" ON "MessageDelivery"("organizationId","createdAt");
CREATE TABLE "Workflow" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "trigger" TEXT NOT NULL, "conditions" JSONB, "steps" JSONB NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Workflow_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Workflow_organizationId_trigger_enabled_idx" ON "Workflow"("organizationId","trigger","enabled");
CREATE TABLE "WorkflowRun" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "workflowId" TEXT NOT NULL, "trigger" TEXT NOT NULL, "context" JSONB NOT NULL, "status" TEXT NOT NULL, "stepsLog" JSONB, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WorkflowRun_pkey" PRIMARY KEY ("id"));
CREATE INDEX "WorkflowRun_organizationId_createdAt_idx" ON "WorkflowRun"("organizationId","createdAt");
ALTER TABLE "MessageTemplate" ADD CONSTRAINT "MessageTemplate_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Broadcast" ADD CONSTRAINT "Broadcast_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MessageDelivery" ADD CONSTRAINT "MessageDelivery_broadcastId_fkey" FOREIGN KEY ("broadcastId") REFERENCES "Broadcast"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Workflow" ADD CONSTRAINT "Workflow_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkflowRun" ADD CONSTRAINT "WorkflowRun_workflowId_fkey" FOREIGN KEY ("workflowId") REFERENCES "Workflow"("id") ON DELETE CASCADE ON UPDATE CASCADE;
